// FUNCTION: BFME2 0x00144DF0 size=160 name=?Render_Delayed_Procedural_Material_Passes@DX8RigidFVFCategoryContainer@@UAEXXZ evidence=N:ledger tier=A
void DX8RigidFVFCategoryContainer::Render_Delayed_Procedural_Material_Passes()
{
	if (!AnyDelayedPassesToRender)
		return;
	AnyDelayedPassesToRender = false;

	DXWrapper::Set_Vertex_Buffer(VertexBuffer);
	DXWrapper::Set_Index_Buffer(IndexBuffer, 0);

	MatPassTaskClass *task = DelayedMatPassHead;
	while (task) {
		task->Peek_Mesh()->Render_Material_Pass(task->Peek_Material_Pass(), IndexBuffer);
		MatPassTaskClass *next = task->Get_Next_Visible();
		delete task;
		task = next;
	}

	DelayedMatPassTail = NULL;
	DelayedMatPassHead = NULL;
}

