typedef MultiListIterator<DX8FVFCategoryContainer> FVFCategoryListIterator;

static void Log_Container_List(FVFCategoryList &container_list, bool only_visible)
{
	FVFCategoryListIterator it(&container_list);
	while (!it.Is_Done()) {
		it.Peek_Obj()->Log(only_visible);
		it.Next();
	}
}

void DX8MeshRendererClass::Log_Statistics_String(bool only_visible)
{
	if (statistics_requested != WW3D::Get_Frame_Count()) return;

	for (int i = 0; i < TextureCategoryContainerListsRigid.Count(); ++i) {
		Log_Container_List(*TextureCategoryContainerListsRigid[i], only_visible);
	}
	Log_Container_List(*TextureCategoryContainerListSkin, only_visible);
}

// FUNCTION: BFME2 0x00145FA0 size=265 name=?Invalidate@DX8MeshRendererClass@@QAEX_N@Z evidence=N:ledger tier=A
static void Invalidate_FVF_Category_Container_List(FVFCategoryList &list)
{
	while (DX8FVFCategoryContainer *fvf_category = list.Remove_Head()) {
		::delete fvf_category;
	}
}

void DX8MeshRendererClass::Invalidate(bool shutdown)
{
	for (int i = 0; i < TextureCategoryContainerListsRigid.Count(); ++i) {
		Invalidate_FVF_Category_Container_List(*TextureCategoryContainerListsRigid[i]);
		::delete TextureCategoryContainerListsRigid[i];
	}
	if (TextureCategoryContainerListSkin) {
		Invalidate_FVF_Category_Container_List(*TextureCategoryContainerListSkin);
		::delete TextureCategoryContainerListSkin;
		TextureCategoryContainerListSkin = NULL;
	}

	if (!shutdown)
		TextureCategoryContainerListSkin = new FVFCategoryList;

	TextureCategoryContainerListsRigid.Delete_All();
}


