{
	PolygonRendererList.Remove(renderer);
	renderer->Set_Texture_Category(NULL);
	if (PolygonRendererList.Peek_Head() == NULL) {
		Container->Remove_Texture_Category(this);
		if (TheDX8MeshRenderer != NULL) {
			TheDX8MeshRenderer->TextureCategoryDeleteList.Add_Tail(this);
		}
	}
}

// FUNCTION: BFME2 0x00146130 size=165 name=?Render_Procedural_Material_Passes@DX8FVFCategoryContainer@@IAE_NXZ evidence=N:ledger tier=A
bool DX8FVFCategoryContainer::Render_Procedural_Material_Passes(void)
{
	const int vertex_buffer_overflow = 0xFFFF;
	MatPassTaskClass *task = VisibleMatPassHead;
	MatPassTaskClass *last_pending = NULL;
	bool tasks_remaining = false;
	bool rendered = false;

	while (task) {
		MeshClass *mesh = task->Peek_Mesh();
		if (mesh->Get_Base_Vertex_Offset() == vertex_buffer_overflow) {
			last_pending = task;
			task = task->Get_Next_Visible();
			tasks_remaining = true;
			continue;
		}

		mesh->Render_Material_Pass(task->Peek_Material_Pass(), IndexBuffer);
		MatPassTaskClass *next = task->Get_Next_Visible();
		rendered = true;
		if (last_pending == NULL) {
			VisibleMatPassHead = next;
		} else {
			last_pending->Set_Next_Visible(next);
		}
		delete task;
		task = next;
	}

	VisibleMatPassTail = tasks_remaining ? last_pending : NULL;
	return rendered;
}

