// FUNCTION: BFME2 0x00148030 size=193 name=?Flush@DX8MeshRendererClass@@QAEXXZ evidence=N:ledger tier=A
static void Render_FVF_Category_Container_List(FVFCategoryList &list)
{
	FVFCategoryListIterator it(&list);
	while (!it.Is_Done()) {
		it.Peek_Obj()->Render();
		it.Next();
	}
}

static void Render_FVF_Category_Container_List_Delayed_Passes(FVFCategoryList &list)
{
	FVFCategoryListIterator it(&list);
	while (!it.Is_Done()) {
		it.Peek_Obj()->Render_Delayed_Procedural_Material_Passes();
		it.Next();
	}
}

void DX8MeshRendererClass::Flush(void)
{
	int i;

	if (!Camera) return;
	Log_Statistics_String(true);

	// Render the FVF categories. Skins must be rendered after the rigid meshes: an object may have its base
	// passes disabled and a translucent procedural material pass rendered instead.
	for (i = 0; i < TextureCategoryContainerListsRigid.Count(); ++i) {
		Render_FVF_Category_Container_List(*TextureCategoryContainerListsRigid[i]);
	}

	Render_FVF_Category_Container_List(*TextureCategoryContainerListSkin);

	// Render the translucent procedural material passes that were applied to meshes that had their base passes
	// disabled.
	for (i = 0; i < TextureCategoryContainerListsRigid.Count(); ++i) {
		Render_FVF_Category_Container_List_Delayed_Passes(*TextureCategoryContainerListsRigid[i]);
	}

	DXWrapper::Set_Vertex_Buffer(0);
	DXWrapper::Set_Index_Buffer(0, 0);
	DXWrapper::Apply_Render_State_Changes();
	DXWrapper::Invalidate_Cached_Render_States();
	DXWrapper::Apply_Default_State();
}

// FUNCTION: BFME2 0x00148100 size=124 name=?Render@DX8RigidFVFCategoryContainer@@UAEXXZ evidence=N:ledger tier=B hypothesis:cohesion
void DX8RigidFVFCategoryContainer::Render(void)
{
	if (!AnythingToRender) return;
	AnythingToRender = false;

	DXWrapper::Set_Vertex_Buffer(VertexBuffer);

	DXWrapper::Set_Index_Buffer(IndexBuffer, 0);

	for (unsigned p = 0; p < Passes; ++p) {
		while (DX8TextureCategoryClass *tex = VisibleTextureCategoryList[p].Remove_Head()) {
			tex->Render();
		}
	}

	Render_Procedural_Material_Passes();
}

